$ErrorActionPreference = 'Stop'
$dir = 'src\editors\website'
if (!(Test-Path (Join-Path $dir 'WebsiteEditor.tsx'))) { throw 'Run from the Onyx Studio root.' }
$patches = @(
  @{ Name = 'WebsiteEditor.tsx'; Hash = '1BEA2375F872B8D8ED33C2B18C403A3D1B264BE09F394897BFFD3E91F4886358'; Data = '' }
  @{ Name = 'websiteTypes.ts'; Hash = '46955591CF9B176B4257817EC9FB71D5848DE6CBFC6D3A9CBFE4249EB1719076'; Data = '' }
  @{ Name = 'websiteExporter.ts'; Hash = '98C09BA770BAE5E96D24A228B2B80B7CE6E0D18CF985A68E3B7112A36231ADAA'; Data = '' }
)
foreach ($p in $patches) {
  $path = Join-Path $dir $p.Name
  if (!(Test-Path $path)) { throw "Missing $path" }
  if ((Get-FileHash -Algorithm SHA256 $path).Hash -ne $p.Hash) {
    throw "File differs from uploaded version: $path. No changes made."
  }
}
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backups = @()
try {
  foreach ($p in $patches) {
    $path = Join-Path $dir $p.Name
    $backup = "$path.$stamp.bak"
    Copy-Item $path $backup
    $backups += @{ Path = $path; Backup = $backup }
    [System.IO.File]::WriteAllBytes((Resolve-Path $path).Path, [Convert]::FromBase64String($p.Data))
    Write-Host "Patched $path"
  }
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
  Write-Host 'Card Components v1 installed successfully.' -ForegroundColor Green
} catch {
  foreach ($item in $backups) { Copy-Item $item.Backup $item.Path -Force }
  Write-Host 'Original files restored.' -ForegroundColor Yellow
  throw
}
